import{_ as t,c as a,o,ak as l}from"./chunks/framework.14-H7uoj.js";const i="/img/png/408_DS/10.png",m=JSON.parse('{"title":"队列的基本概念","titleTemplate":"数据结构","description":"队列的基本概念","frontmatter":{"title":"队列的基本概念","titleTemplate":"数据结构","description":"队列的基本概念","layout":"doc","navbar":true,"sidebar":true,"aside":true,"outline":"deep","lastUpdated":true,"prev":false,"next":false,"tags":["数据结构","队列","基本概念","408"]},"headers":[],"relativePath":"post/kaoyan/408/408_DS/03/408_DS_6.md","filePath":"post/kaoyan/408/408_DS/03/408_DS_6.md","lastUpdated":1756206938000}'),r={name:"post/kaoyan/408/408_DS/03/408_DS_6.md"};function d(s,e,n,c,p,u){return o(),a("div",null,e[0]||(e[0]=[l('<h1 id="队列的基本概念" tabindex="-1">队列的基本概念 <a class="header-anchor" href="#队列的基本概念" aria-label="Permalink to &quot;队列的基本概念&quot;">​</a></h1><h2 id="队列的定义" tabindex="-1">队列的定义 <a class="header-anchor" href="#队列的定义" aria-label="Permalink to &quot;队列的定义&quot;">​</a></h2><p>队列（Queue）简称队，也是一种操作受限的线性表，只允许在表的一端进行插入，而在表的另一端进行删除。</p><p>向队列中插入元素称为入队或进队；删除元素称为出队或离队。这和我们日常生活中的排队是一致的，最早排队的也是最早离队的，其操作的特性是先进先出（First In First Out，FIFO），如图所示。</p><br><div style="display:flex;flex-direction:column;align-items:center;"><img src="'+i+'" alt="链栈" width="350px" style="border-radius:10px;"></div><br><ul><li><strong>队头（Front）</strong>：允许删除的一端，也称队首。</li><li><strong>队尾（Rear）</strong>：允许插入的一端。</li><li><strong>空队列</strong>：不含任何元素的空表。</li></ul><h2 id="队列常见的基本操作" tabindex="-1">队列常见的基本操作 <a class="header-anchor" href="#队列常见的基本操作" aria-label="Permalink to &quot;队列常见的基本操作&quot;">​</a></h2><ul><li><code>InitQueue(&amp;Q)</code> ：初始化队列，构造一个空队列 Q 。</li><li><code>QueueEmpty(Q)</code>：判队列空，若队列 Q 为空返回 <code>true</code>，否则返回 <code>false</code>。</li><li><code>EnQueue(&amp;Q, x)</code>：入队，若队列 Q 未满，将 x 加入，使之成为新的队尾。</li><li><code>DeQueue(&amp;Q, &amp;x)</code>：出队，若队列 Q 非空，删除队首元素，并用 x 返回。</li><li><code>GetHead(Q, &amp;x)</code>：读队首元素，若队列 Q 非空，则将队首元素赋值给 x 。</li></ul><blockquote><p>需要注意的是，栈和队列是操作受限的线性表，因此不是任何对线性表的操作都可以作为栈和队列的操作。比如，不可以随便读取栈或队列中间的某个数据。</p></blockquote>',11)]))}const h=t(r,[["render",d]]);export{m as __pageData,h as default};
